contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amount to collect and an initial deposit amount to set up state.
    // The function is payable so we can fund this contract to forward ETH to c when depositing.
    function run(uint initialDeposit, uint collectAmount, address payable _senderDummy) public payable {
        require(address(this).balance >= initialDeposit, "need funds to deposit");

        // Ensure the c.MinSum is settable before initialization: call SetMinSum if needed.
        // We don't know MinSum value, so we won't change it; observe it instead.
        uint minSum = c.MinSum();

        // Make an initial deposit into c from this contract so that c.balances(this) increases.
        // Deposit is a state-changing call and must be a top-level statement.
        c.Deposit{value: initialDeposit}();

        // Read balance after deposit
        uint balBefore = c.balances(address(this));
        // Sanity: balBefore should be at least initialDeposit due to Deposit behavior (checked separately by prover)

        // Attempt to call Collect for collectAmount and capture whether it reverts.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractEthAfter = address(c).balance;
        uint contractEthBefore = contractEthAfter; // approximate: we only have after observed, but relation uses balances too

        // The assertion encodes the general rule:
        // If Collect did not revert then three conditions hold:
        // 1) collectAmount <= balBefore
        // 2) balAfter == balBefore - collectAmount
        // 3) address(c).balance decreased by collectAmount (i.e., contract had sent collectAmount out)
        // Otherwise (if reverted) at least one of the preconditions for success was violated:
        //    either balBefore < minSum or balBefore < collectAmount
        // Note: we observe address(c).balance after the call and compare with expected value using balBefore and balAfter.

        // To avoid relying on historical contract balance before the call (not directly observable separately here),
        // we derive the ETH moved by comparing balBefore and balAfter when call succeeded: it must equal collectAmount.

        assert(
            (!reverted && balBefore >= minSum && balBefore >= collectAmount && balAfter + collectAmount == balBefore)
            || (reverted && (balBefore < minSum || balBefore < collectAmount))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run: caller (this contract) deposits some amount, then attempts to Collect some amount.
    // params: depositAmount to send to Deposit, collectAmount to request in Collect.
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure fresh state: SetMinSum to 0 before initializing to allow collect when needed.
        // These calls are allowed since intitalized is false initially on the fresh c deployed by checker.
        // They may revert if intitalized already true; we ignore reverts here by using try/catch.
        try c.SetMinSum(0) {
        } catch {
        }
        try c.SetLogFile(address(this)) {
        } catch {
        }

        // Record balances before interactions
        uint beforeUserBal = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // Deposit depositAmount into c from this contract
        c.Deposit{value: depositAmount}();

        // After deposit, read balances
        uint afterDepositUserBal = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // Try to Collect collectAmount and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read balances after collect attempt
        uint afterCollectUserBal = c.balances(address(this));
        uint afterCollectContractEth = address(c).balance;

        // General rule to assert:
        // If Collect did not revert then:
        //  - user's recorded balance decreased by exactly collectAmount (no under/overflow in public view)
        //  - the contract's Ether balance decreased by at least collectAmount (it may be equal or more if other transfers happened,
        //    but in this single-actor scenario it should decrease by exactly collectAmount; we assert >= to be robust)
        // If Collect reverted then balances remain unchanged compared to afterDeposit state.
        assert(
            (!collectReverted && afterDepositUserBal >= collectAmount && afterCollectUserBal + collectAmount == afterDepositUserBal && afterCollectContractEth + collectAmount <= afterDepositContractEth)
            || (collectReverted && afterCollectUserBal == afterDepositUserBal && afterCollectContractEth == afterDepositContractEth)
        );
    }

    // Allow receiving Ether when Log.AddMessage might call back (not expected but safe)
    receive() external payable {}
}
